tion?->tax_address['city'] ?? '' }}"></label><label>State<input name="tax_address[state]" value="{{ $editingMarket?->pickupLocation?->tax_address['state'] ?? 'SC' }}" maxlength="2"></label><label>ZIP code<input name="tax_address[postal_code]" value="{{ $editingMarket?->pickupLocation?->tax_address['postal_code'] ?? '' }}" pattern="[0-9]{5}(-[0-9]{4})?"></label><input type="hidden" name="tax_address[country]" value="US"><label class="check full"><input type="checkbox" name="offer_pickup" value="1" @checked($editingMarket?->pickup_location_id)>Offer order pickup at this market for approved participating makers.</label><label class="full">Pickup instructions<textarea name="pickup_instructions">{{ $editingMarket?->pickup_instructions }}</textarea></label><button class="button">{{ $editingMarket ? 'Save market' : 'Create market or show' }}</button></form>
